const page1 = $('FORM — Create Details').first().json;
const page2 = $('FORM — Assign Team & Equipment').first().json;

const projectName = String(page1['Project Name'] || '').trim();
const client = String(page1.Client || '').trim();
if (!projectName || !client) throw new Error('Project Name and Client are required.');

function cleanPerson(v) {
  const s = String(v || '').trim();
  if (!s || s === '(None)') return '';
  return s;
}

function parseEquipmentSelections(raw) {
  let values = [];
  if (Array.isArray(raw)) values = raw;
  else if (raw && typeof raw === 'object') {
    values = Object.values(raw).flatMap(v => Array.isArray(v) ? v : [v]);
  } else if (typeof raw === 'string' && raw.trim()) {
    values = raw.split(/,|\n/).map(s => s.trim());
  }

  return values
    .map(v => String(v || '').trim())
    .filter(v => v && !v.includes('No available equipment'))
    .map(v => {
      const parts = v.split('|');
      const id = (parts[0] || '').trim();
      const rest = (parts.slice(1).join('|') || '').trim();
      const name = rest.replace(/\(.*\)$/, '').trim();
      return { id, name, label: v };
    })
    .filter(v => v.id);
}

const selectedEquipment = parseEquipmentSelections(page2['Required Equipment']);
const developer = cleanPerson(page2.Developer);
const designer = cleanPerson(page2.Designer);
const installer = cleanPerson(page2.Installer);
const startDate = String(page1['Start Date'] || '').trim();
const deadline = String(page1.Deadline || '').trim();
const requiredEquipment = selectedEquipment.map(e => e.label).join('\n');

const submissionKey = [
  projectName.toLowerCase(),
  client.toLowerCase(),
  startDate,
  deadline,
  selectedEquipment.map(e => e.id).sort().join(','),
  developer.toLowerCase(),
  designer.toLowerCase(),
  installer.toLowerCase(),
].join('|');

return [{
  json: {
    project_name: projectName,
    client,
    project_type: String(page1['Project Type'] || '').trim(),
    description: String(page1.Description || '').trim(),
    technology: String(page1.Technology || '').trim(),
    start_date: startDate,
    deadline,
    priority: String(page1.Priority || 'Medium').trim() || 'Medium',
    status: String(page1.Status || 'New').trim() || 'New',
    developer,
    designer,
    installer,
    location: String(page1.Location || '').trim(),
    required_equipment_raw: requiredEquipment,
    selected_equipment_ids: selectedEquipment.map(e => e.id),
    client_assets_status: String(page1['Client Assets'] || 'Unknown').trim() || 'Unknown',
    notes: String(page1.Notes || '').trim(),
    submission_key: submissionKey,
    now: new Date().toISOString(),
  }
}];

const input = $('Normalize Form Input').first().json;
const projects = $('READ — Projects').all().map(i => i.json).filter(r => r.Project_ID || r.Project_Name);
const equipment = $('READ — Equipment').all().map(i => i.json).filter(r => r.Equipment_ID || r.Equipment_Name);
const reservations = $('READ — Reservations').all().map(i => i.json).filter(r => r.Reservation_ID || r.Equipment_ID);
const team = $('READ — Team').all().map(i => i.json).filter(r => r.Team_ID || r.Name);

const existing = projects.find(p => String(p.Submission_Key || '') === input.submission_key);
if (existing) {
  return [{
    json: {
      is_duplicate: true,
      summary: {
        project_created: false,
        project_id: existing.Project_ID,
        message: 'Duplicate submission detected. Existing project reused.',
        team_assigned: [],
        equipment_available: [],
        equipment_unavailable: [],
        current_blockers: existing.Current_Blocker || '',
      },
      project_row: null,
      reservation_rows: [],
      equipment_rows: [],
      team_rows: [],
      notification_rows: [],
    }
  }];
}

const year = new Date().getFullYear();
const prefix = 'PRJ-' + year + '-';
let maxNum = 0;
for (const p of projects) {
  const m = String(p.Project_ID || '').match(new RegExp('^PRJ-' + year + '-(\\d+)$'));
  if (m) maxNum = Math.max(maxNum, Number(m[1]));
}
const projectId = prefix + String(maxNum + 1).padStart(3, '0');

function parseEquipment(raw) {
  if (!raw) return [];
  return String(raw).split(/\n|,|;/).map(s => s.trim()).filter(Boolean).map(line => {
    let qty = 1;
    let name = line;
    const m1 = line.match(/^(.+?)\s*[xX×]\s*(\d+)$/);
    const m2 = line.match(/^(\d+)\s*[xX×]\s*(.+)$/);
    if (m1) { name = m1[1].trim(); qty = Number(m1[2]); }
    else if (m2) { qty = Number(m2[1]); name = m2[2].trim(); }
    return { name, qty: Number.isFinite(qty) && qty > 0 ? qty : 1 };
  });
}

function overlaps(aStart, aEnd, bStart, bEnd) {
  const as = new Date(aStart || 0).getTime();
  const ae = new Date(aEnd || aStart || 0).getTime();
  const bs = new Date(bStart || 0).getTime();
  const be = new Date(bEnd || bStart || 0).getTime();
  if (!as || !bs) return false;
  return as <= be && bs <= ae;
}

const selectedIds = Array.isArray(input.selected_equipment_ids) ? input.selected_equipment_ids : [];
// SELECTED_EQUIPMENT_IDS
const requested = parseEquipment(input.required_equipment_raw);
const reservedStatuses = new Set(['Reserved', 'Active']);
const availableEquipment = [];
const unavailable = [];
const reservationRows = [];
const equipmentRows = [];

if (selectedIds.length) {
  for (const id of selectedIds) {
    const eq = equipment.find(e => String(e.Equipment_ID) === String(id));
    if (!eq) {
      unavailable.push({ name: id, requested: 1, available: 0 });
      continue;
    }
    const status = String(eq.Status || '');
    const conflicting = reservations.some(r =>
      String(r.Equipment_ID) === String(eq.Equipment_ID) &&
      reservedStatuses.has(String(r.Status || '')) &&
      overlaps(input.start_date, input.deadline, r.Start_Date, r.End_Date)
    );
    if (conflicting || ['Broken', 'Maintenance', 'Installed', 'Reserved'].includes(status)) {
      unavailable.push({ name: eq.Equipment_Name + ' (' + eq.Equipment_ID + ')', requested: 1, available: 0 });
      continue;
    }
    availableEquipment.push({ name: eq.Equipment_Name, id: eq.Equipment_ID });
    const reservationId = 'RES-' + projectId + '-' + eq.Equipment_ID;
    reservationRows.push({
      Reservation_ID: reservationId,
      Equipment_ID: eq.Equipment_ID,
      Equipment_Name: eq.Equipment_Name,
      Project_ID: projectId,
      Project_Name: input.project_name,
      Reserved_By: 'Studio OS',
      Start_Date: input.start_date,
      End_Date: input.deadline,
      Status: 'Reserved',
      Notes: 'Selected from form dropdown',
      Created_At: input.now,
    });
    equipmentRows.push({
      Equipment_ID: eq.Equipment_ID,
      Equipment_Name: eq.Equipment_Name,
      Category: eq.Category || '',
      Status: 'Reserved',
      Location: eq.Location || '',
      Current_Project: projectId,
      Notes: eq.Notes || '',
    });
  }
} else {
  for (const req of requested) {
    const matches = equipment.filter(e => String(e.Equipment_Name || '').toLowerCase() === req.name.toLowerCase());
    const free = matches.filter(eq => {
      const status = String(eq.Status || '');
      if (['Broken', 'Maintenance'].includes(status)) return false;
      if (status === 'Installed') return false;
      const conflicting = reservations.some(r =>
        String(r.Equipment_ID) === String(eq.Equipment_ID) &&
        reservedStatuses.has(String(r.Status || '')) &&
        overlaps(input.start_date, input.deadline, r.Start_Date, r.End_Date)
      );
      return !conflicting && (status === 'Available' || status === '');
    });

    const take = free.slice(0, req.qty);
    if (take.length < req.qty) {
      unavailable.push({ name: req.name, requested: req.qty, available: take.length });
    }
    for (const eq of take) {
      availableEquipment.push({ name: eq.Equipment_Name, id: eq.Equipment_ID });
      const reservationId = 'RES-' + projectId + '-' + eq.Equipment_ID;
      reservationRows.push({
        Reservation_ID: reservationId,
        Equipment_ID: eq.Equipment_ID,
        Equipment_Name: eq.Equipment_Name,
        Project_ID: projectId,
        Project_Name: input.project_name,
        Reserved_By: 'Studio OS',
        Start_Date: input.start_date,
        End_Date: input.deadline,
        Status: 'Reserved',
        Notes: 'Auto-reserved on project create',
        Created_At: input.now,
      });
      equipmentRows.push({
        Equipment_ID: eq.Equipment_ID,
        Equipment_Name: eq.Equipment_Name,
        Category: eq.Category || '',
        Status: 'Reserved',
        Location: eq.Location || '',
        Current_Project: projectId,
        Notes: eq.Notes || '',
      });
    }
  }
}

const blockerText = unavailable.length
  ? unavailable.map(u => `${u.name}: need ${u.requested}, available ${u.available}`).join('; ')
  : '';

const allowedStatuses = new Set([
  'New','Planning','Waiting Assets','Development','Internal Review',
  'Client Review','Changes Required','Approved','Deployment','Completed','Blocked'
]);
let status = String(input.status || 'New').trim() || 'New';
if (!allowedStatuses.has(status)) status = 'New';

// Auto-block only when equipment conflicts and user left default New
if (unavailable.length && status === 'New') status = 'Blocked';

const projectRow = {
  Project_ID: projectId,
  Project_Name: input.project_name,
  Client: input.client,
  Project_Type: input.project_type,
  Description: input.description,
  Technology: input.technology,
  Start_Date: input.start_date,
  Deadline: input.deadline,
  Priority: input.priority,
  Status: status,
  Developer: input.developer,
  Designer: input.designer,
  Installer: input.installer,
  Location: input.location,
  Client_Assets_Status: input.client_assets_status,
  Demo_Link: '',
  Build_Link: '',
  Website_Link: '',
  Testing_Instructions: '',
  Installation_Instructions: '',
  Last_Submitted_By: '',
  Last_Update_Notes: input.notes || '',
  Current_Blocker: blockerText,
  Created_At: input.now,
  Updated_At: input.now,
  Submission_Key: input.submission_key,
};

const teamRows = [];
const teamWarnings = [];
const notificationRows = [];
const assigned = [];

function assignPerson(name, role) {
  if (!name) return;
  const person = team.find(t => String(t.Name || '').toLowerCase() === name.toLowerCase());
  if (!person) {
    teamWarnings.push(`${role} "${name}" not found in Team sheet`);
    notificationRows.push({
      Notification_ID: 'NTF-' + projectId + '-' + role.toUpperCase() + '-MISSING',
      Project_ID: projectId,
      Recipient: 'Studio Lead',
      Channel: 'Dashboard',
      Message: `Warning: assigned ${role} "${name}" was not found in Team sheet for project ${input.project_name}.`,
      Type: 'Team Warning',
      Priority: 'WARNING',
      Status: 'Pending',
      Dedup_Key: projectId + '|missing|' + role + '|' + name.toLowerCase(),
      Created_At: input.now,
      Sent_At: '',
    });
    return;
  }
  const currentStatus = String(person.Status || '');
  const currentProject = String(person.Current_Project || '');
  if (currentStatus === 'Working' && currentProject && currentProject !== projectId) {
    teamWarnings.push(`${name} already Working on ${currentProject}`);
    notificationRows.push({
      Notification_ID: 'NTF-' + projectId + '-' + role.toUpperCase() + '-BUSY',
      Project_ID: projectId,
      Recipient: 'Studio Lead',
      Channel: 'Dashboard',
      Message: `Warning: ${name} is already Working on ${currentProject}, but was also assigned as ${role} on ${input.project_name}.`,
      Type: 'Team Warning',
      Priority: 'WARNING',
      Status: 'Pending',
      Dedup_Key: projectId + '|busy|' + name.toLowerCase() + '|' + currentProject,
      Created_At: input.now,
      Sent_At: '',
    });
  } else {
    teamRows.push({
      Team_ID: person.Team_ID,
      Name: person.Name,
      Role: person.Role || role,
      Email: person.Email || '',
      Phone: person.Phone || '',
      Status: 'Working',
      Current_Project: projectId,
      Available_From: person.Available_From || '',
      Notes: person.Notes || '',
    });
  }
  assigned.push({ name: person.Name, role, email: person.Email || '' });
  const roleLine = role === 'Developer'
    ? `You are assigned as Developer.\nTechnology: ${input.technology || 'n/a'}.`
    : role === 'Designer'
      ? `You are assigned as Designer.\nClient assets status: ${input.client_assets_status}.`
      : `You are assigned as Installer.\nLocation: ${input.location || 'n/a'}.`;
  notificationRows.push({
    Notification_ID: 'NTF-' + projectId + '-' + role.toUpperCase(),
    Project_ID: projectId,
    Recipient: person.Name,
    Channel: 'Dashboard',
    Message: `New project assigned: ${input.project_name}.\nClient: ${input.client}.\n${roleLine}\nDeadline: ${input.deadline || 'n/a'}.\nCurrent status: ${status}.\nBlockers: ${blockerText || 'None'}.\nNotes: ${input.notes || 'None'}`,
    Type: 'Assignment',
    Priority: 'NORMAL',
    Status: 'Pending',
    Dedup_Key: projectId + '|assign|' + role + '|' + person.Name.toLowerCase(),
    Created_At: input.now,
    Sent_At: '',
  });
}

assignPerson(input.developer, 'Developer');
assignPerson(input.designer, 'Designer');
assignPerson(input.installer, 'Installer');

if (unavailable.length) {
  const msg = `Project ${input.project_name} requires equipment that is not fully available. ${blockerText}`;
  notificationRows.push({
    Notification_ID: 'NTF-' + projectId + '-EQUIP',
    Project_ID: projectId,
    Recipient: 'Studio Lead',
    Channel: 'Dashboard',
    Message: msg,
    Type: 'Equipment Blocker',
    Priority: 'HIGH',
    Status: 'Pending',
    Dedup_Key: projectId + '|equip|' + blockerText,
    Created_At: input.now,
    Sent_At: '',
  });
}

// RESERVATIONS_NOTIFICATIONS_DISABLED
reservationRows.length = 0;
notificationRows.length = 0;

return [{
  json: {
    is_duplicate: false,
    project_row: projectRow,
    reservation_rows: reservationRows,
    equipment_rows: equipmentRows,
    team_rows: teamRows,
    notification_rows: notificationRows,
    summary: {
      project_created: true,
      project_id: projectId,
      project_name: input.project_name,
      status,
      team_assigned: assigned,
      team_warnings: teamWarnings,
      equipment_available: availableEquipment,
      equipment_unavailable: unavailable,
      current_blockers: blockerText || 'None',
      notifications_queued: notificationRows.length,
    },
  }
}];

const root = $('Process Project Logic').first().json;
const rows = root.equipment_rows || [];
if (!rows.length) return [{ json: { _skip: true } }];
return rows.map(r => ({ json: { ...r, _skip: false } }));

const root = $('Process Project Logic').first().json;
const rows = root.team_rows || [];
if (!rows.length) return [{ json: { _skip: true } }];
return rows.map(r => ({ json: { ...r, _skip: false } }));

const team = $('READ — Team').all().map(i => i.json).filter(r => r.Name || r.Team_ID);
const equipment = $('READ — Equipment').all().map(i => i.json).filter(r => r.Equipment_ID || r.Equipment_Name);

const teamOptions = team
  .filter(t => String(t.Status || '') !== 'Off')
  .map(t => ({ option: String(t.Name).trim() }))
  .filter(o => o.option);

const uniqueTeam = [];
const seen = new Set();
for (const o of teamOptions) {
  const key = o.option.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  uniqueTeam.push(o);
}

const none = [{ option: '(None)' }];
const availableEq = equipment.filter(e => {
  const s = String(e.Status || 'Available');
  return s === 'Available' || s === '';
});

const eqOptions = availableEq.map(e => ({
  option: String(e.Equipment_ID) + ' | ' + String(e.Equipment_Name) + (e.Location ? ' (' + e.Location + ')' : ''),
}));

const form_fields = [
  {
    fieldLabel: 'Developer',
    fieldType: 'dropdown',
    requiredField: false,
    fieldOptions: { values: none.concat(uniqueTeam) },
  },
  {
    fieldLabel: 'Designer',
    fieldType: 'dropdown',
    requiredField: false,
    fieldOptions: { values: none.concat(uniqueTeam) },
  },
  {
    fieldLabel: 'Installer',
    fieldType: 'dropdown',
    requiredField: false,
    fieldOptions: { values: none.concat(uniqueTeam) },
  },
  {
    fieldLabel: 'Required Equipment',
    fieldType: 'checkbox',
    requiredField: false,
    fieldOptions: {
      values: eqOptions.length ? eqOptions : [{ option: '(No available equipment)' }],
    },
  },
];

if (!uniqueTeam.length) {
  throw new Error('No team members found in Team sheet. Add rows first.');
}

return [{ json: { form_fields } }];

const items = $input.all();
if (!items.length) {
  return [{ json: { _empty_sheet: true } }];
}
return items;

const items = $input.all();
if (!items.length) {
  return [{ json: { _empty_sheet: true } }];
}
return items;

const projects = $('READ — Projects For Update').all().map(i => i.json).filter(r => r.Project_ID || r.Project_Name);
const team = $('READ — Team For Update').all().map(i => i.json).filter(r => r.Name || r.Team_ID);

const options = projects
  .map(p => {
    const id = String(p.Project_ID || '').trim();
    const name = String(p.Project_Name || '').trim();
    const client = String(p.Client || '').trim();
    const status = String(p.Status || '').trim();
    if (!id && !name) return null;
    const label = [id || 'NO-ID', client || 'No client', name || 'Untitled', status ? '(' + status + ')' : '']
      .filter(Boolean)
      .join(' | ');
    return { option: label };
  })
  .filter(Boolean);

if (!options.length) {
  options.push({ option: 'No projects found — create one first' });
}

const teamOptions = [];
const seen = new Set();
for (const t of team) {
  if (String(t.Status || '') === 'Off') continue;
  const name = String(t.Name || '').trim();
  if (!name || seen.has(name.toLowerCase())) continue;
  seen.add(name.toLowerCase());
  teamOptions.push({ option: name });
}
if (!teamOptions.length) {
  teamOptions.push({ option: 'No team members found' });
}

const statusOptions = ["New","Planning","Waiting Assets","Development","Internal Review","Client Review","Changes Required","Approved","Deployment","Completed","Blocked"].map(s => ({ option: s }));

return [{
  json: {
    form_fields: [
      {
        fieldLabel: 'Project',
        fieldType: 'dropdown',
        requiredField: true,
        fieldOptions: { values: options },
      },
      {
        fieldLabel: 'Submitted By',
        fieldType: 'dropdown',
        requiredField: true,
        fieldOptions: { values: teamOptions },
      },
      {
        fieldLabel: 'Status',
        fieldType: 'dropdown',
        requiredField: false,
        fieldOptions: { values: statusOptions },
      },
      {
        fieldLabel: 'Demo Link',
        fieldType: 'text',
        placeholder: 'Video / Loom / Drive demo',
      },
      {
        fieldLabel: 'Build Link',
        fieldType: 'text',
        placeholder: 'Unity build / APK / zip',
      },
      {
        fieldLabel: 'Website Link',
        fieldType: 'text',
        placeholder: 'Staging or live URL',
      },
      {
        fieldLabel: 'Testing Instructions',
        fieldType: 'textarea',
        placeholder: 'How to test this build/demo',
      },
      {
        fieldLabel: 'Installation Instructions',
        fieldType: 'textarea',
        placeholder: 'Install / deploy steps',
      },
      {
        fieldLabel: 'Notes',
        fieldType: 'textarea',
        placeholder: 'What changed / blockers',
      },
    ],
  },
}];

const page = $('FORM — Update Project').first().json;
const projects = $('READ — Projects For Update').all().map(i => i.json).filter(r => r.Project_ID || r.Project_Name);

const projectLabel = String(page.Project || '').trim();
if (!projectLabel || projectLabel.startsWith('No projects found')) {
  throw new Error('Select a valid project to update.');
}

const projectId = projectLabel.split('|')[0].trim();
const existing = projects.find(p => String(p.Project_ID || '').trim() === projectId);
if (!existing) {
  throw new Error('Project not found: ' + projectId);
}

const submittedBy = String(page['Submitted By'] || '').trim();
if (!submittedBy || submittedBy === 'No team members found') throw new Error('Submitted By is required — pick a team member.');

const now = new Date().toISOString();
const pick = (label, fallbackKey) => {
  const v = String(page[label] ?? '').trim();
  if (v) return v;
  return existing[fallbackKey] ?? '';
};

const statusRaw = String(page.Status || '').trim();
const allowed = new Set(["New","Planning","Waiting Assets","Development","Internal Review","Client Review","Changes Required","Approved","Deployment","Completed","Blocked"]);
let status = statusRaw || String(existing.Status || 'Development');
if (statusRaw && !allowed.has(statusRaw)) status = String(existing.Status || 'Development');

const row = {
  Project_ID: existing.Project_ID,
  Project_Name: existing.Project_Name || '',
  Client: existing.Client || '',
  Project_Type: existing.Project_Type || '',
  Description: existing.Description || '',
  Technology: existing.Technology || '',
  Start_Date: existing.Start_Date || '',
  Deadline: existing.Deadline || '',
  Priority: existing.Priority || '',
  Status: status,
  Developer: existing.Developer || '',
  Designer: existing.Designer || '',
  Installer: existing.Installer || '',
  Location: existing.Location || '',
  Client_Assets_Status: existing.Client_Assets_Status || '',
  Demo_Link: pick('Demo Link', 'Demo_Link'),
  Build_Link: pick('Build Link', 'Build_Link'),
  Website_Link: pick('Website Link', 'Website_Link'),
  Testing_Instructions: pick('Testing Instructions', 'Testing_Instructions'),
  Installation_Instructions: pick('Installation Instructions', 'Installation_Instructions'),
  Current_Blocker: existing.Current_Blocker || '',
  Created_At: existing.Created_At || '',
  Updated_At: now,
  Submission_Key: existing.Submission_Key || '',
  Last_Submitted_By: submittedBy,
  Last_Update_Notes: String(page.Notes || '').trim() || (existing.Last_Update_Notes || ''),
};

return [{
  json: {
    project_row: row,
    summary: {
      action: 'update',
      project_id: row.Project_ID,
      project_name: row.Project_Name,
      status: row.Status,
      submitted_by: submittedBy,
      demo_link: row.Demo_Link,
      build_link: row.Build_Link,
      website_link: row.Website_Link,
    },
  },
}];
